import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/ko/git-history-card.png",l="/relio/shots/ko/git-merge-tab.png",m=JSON.parse('{"title":"Git으로 함께 쓰기·합치기","description":"","frontmatter":{},"headers":[],"relativePath":"quick/git.md","filePath":"quick/git.md"}'),s={name:"quick/git.md"};function d(c,e,n,g,p,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="git으로-함께-쓰기·합치기" tabindex="-1">Git으로 함께 쓰기·합치기 <a class="header-anchor" href="#git으로-함께-쓰기·합치기" aria-label="Permalink to &quot;Git으로 함께 쓰기·합치기&quot;">​</a></h1><p><code>.erm</code> 파일을 Git 저장소에 두고 여럿이 고칠 때, Relio는 차이를 작게 저장하고 충돌을 모델 단위로 합칩니다.</p><h2 id="저장소-준비" tabindex="-1">저장소 준비 <a class="header-anchor" href="#저장소-준비" aria-label="Permalink to &quot;저장소 준비&quot;">​</a></h2><ol><li>도구 › 환경 설정 › 일반의 **&quot;Git에 맞춰 정렬해 저장&quot;**이 켜져 있는지 확인합니다(기본 켜짐). 목록 순서를 고정해 Git 차이를 작게 만들고, ERMaster에서도 그대로 열립니다.</li><li>저장소의 <code>.gitattributes</code>에 한 줄을 넣어 줄 끝을 맞춥니다.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.erm text eol=lf merge=relio</span></span></code></pre></div><p><code>merge=relio</code>는 아래 &quot;git merge도 모델 단위로&quot;를 등록했을 때 쓰입니다.</p><h2 id="이력-보기와-비교" tabindex="-1">이력 보기와 비교 <a class="header-anchor" href="#이력-보기와-비교" aria-label="Permalink to &quot;이력 보기와 비교&quot;">​</a></h2><p>파일 › Git 이력(또는 상태 표시줄의 브랜치 이름)을 엽니다. 맨 위 카드가 직전 버전과 비교한 요약(<code>테이블 +1 · 컬럼 +2 ~3</code>)을 보여 주고, 누르면 비교 화면이 열립니다. Relio는 저장소에 아무것도 쓰지 않습니다.</p><figure class="shot" data-scene="git-history-card"><img src="'+r+'" alt="Git 이력 패널 — 최신 커밋 카드와 변경 요약" loading="lazy"><figcaption>Git 이력 패널 — 최신 커밋 카드와 변경 요약</figcaption></figure><h2 id="합치기" tabindex="-1">합치기 <a class="header-anchor" href="#합치기" aria-label="Permalink to &quot;합치기&quot;">​</a></h2><p>같은 파일을 두 곳에서 고쳤을 때 줄이 아니라 테이블·컬럼·관계 단위로 합칩니다. 양쪽이 각자 더한 것은 저절로 들어오고, 같은 칸을 다르게 고친 것만 고르면 됩니다.</p><ol><li>여는 길을 고릅니다. <ul><li>열어 둔 파일이 바깥에서 바뀌었다는 알림 → <strong>합치기…</strong></li><li>Git 병합 충돌이 난 파일 → 파일 › 비교·병합 › Git 병합 충돌 풀기…</li><li>다른 브랜치와 → 파일 › 비교·병합 › 다른 브랜치 버전과 합치기…</li></ul></li><li>합치기 탭에서 충돌마다 <kbd>1</kbd> 내 쪽 · <kbd>2</kbd> 바깥 쪽 · <kbd>3</kbd> 둘 다를 고릅니다. <kbd>F8</kbd>로 다음 충돌로 갑니다.</li><li>남은 충돌이 0이면 <kbd>Ctrl</kbd>+<kbd>Enter</kbd>로 적용하고 저장합니다. 합친 결과 전체가 되돌리기 한 번으로 돌아갑니다. Git 충돌이었다면 저장한 뒤 <code>git add</code>로 마칩니다.</li></ol><figure class="shot" data-scene="git-merge-tab"><img src="'+l+'" alt="합치기 탭 — 충돌 항목과 결과 미리보기" loading="lazy"><figcaption>합치기 탭 — 충돌 항목과 결과 미리보기</figcaption></figure><h2 id="git-merge도-모델-단위로" tabindex="-1">git merge도 모델 단위로 <a class="header-anchor" href="#git-merge도-모델-단위로" aria-label="Permalink to &quot;git merge도 모델 단위로&quot;">​</a></h2><p>명령줄 <code>relio merge</code>를 Git merge driver로 등록하면 <code>git merge</code>·<code>git rebase</code>가 <code>.erm</code>을 자동으로 모델 단위로 합칩니다. 등록은 Git 설정이라 저장소에 따라가지 않으므로, 병합하는 사람마다 자기 PC에 등록해야 합니다.</p><div class="warning custom-block"><p class="custom-block-title">주의</p><p>설치 때 &quot;명령줄에서 relio 쓰기&quot;를 켜지 않았으면 <code>relio</code>가 PATH에 없으므로 <code>relio.exe</code> 전체 경로로 등록하고(도움말 › Relio 정보의 <strong>명령줄 경로 복사</strong>), 등록한 뒤 경로가 맞는지 꼭 확인하세요. 등록 명령과 확인 방법은 <a href="/relio/features/cli#git-merge-driver">명령줄 › Git merge driver</a>에 있습니다.</p></div><p><strong>자세히</strong> → <a href="/relio/features/git">Git과 합치기</a> · <a href="/relio/features/cli">명령줄</a></p>',17)])])}const b=t(s,[["render",d]]);export{m as __pageData,b as default};
